DECLARE @transactions_count BIGINT;
DECLARE @auth_count         BIGINT;
DECLARE @batch_id    NVARCHAR(200) = '@{pipeline().parameters.batch_id}';
DECLARE @process_date DATE          = '@{pipeline().parameters.process_date}';

-- Count rows written to silver.transactions for this batch
SELECT @transactions_count = COUNT(*)
FROM   silver.transactions
WHERE  batch_id     = @batch_id
  AND  process_date = @process_date;

-- Count rows written to silver.auth_events for this batch
SELECT @auth_count = COUNT(*)
FROM   silver.auth_events
WHERE  batch_id     = @batch_id
  AND  process_date = @process_date;

-- Fail the pipeline immediately if either table has zero rows
IF @transactions_count = 0
    RAISERROR('Silver quality check FAILED: silver.transactions has 0 rows for batch_id=%s, process_date=%s. Pipeline aborted.', 16, 1, @batch_id, @process_date);

IF @auth_count = 0
    RAISERROR('Silver quality check FAILED: silver.auth_events has 0 rows for batch_id=%s, process_date=%s. Pipeline aborted.', 16, 1, @batch_id, @process_date);

-- Return metrics for downstream SetVariable activities
SELECT
    @batch_id             AS batch_id,
    @process_date         AS process_date,
    @transactions_count   AS transactions_row_count,
    @auth_count           AS auth_row_count,
    'PASSED'              AS validation_status,
    GETUTCDATE()          AS validated_at;
